messages.content:
```json
{
  "sop_id": "process-invoice",
  "milestones": [
    {
      "id": "M1",
      "target": "One invoice record for Sharma Logistics exists with the correct details.",
      "sop_step": "PI-5",
      "predicates": [
        {
          "read": "list_invoices",
          "where": {
            "vendor": 1,
            "status": "any"
          },
          "expect": {
            "invoice_no": "INV-1043",
            "invoice_date": "2026-10-03",
            "due_date": "2026-11-02",
            "po_number": "PO-2026-0412",
            "amount_paise": 6240000,
            "tax_paise": 951864,
            "vendor_id": 1,
            "vendor_name": "Sharma Logistics Pvt Ltd"
          }
        }
      ]
    },
    {
      "id": "M2",
      "target": "The invoice record shows the source PDF sharma_INV-1043.pdf attached.",
      "sop_step": "PI-6",
      "after": [
        "M1"
      ],
      "predicates": [
        {
          "read": "get_invoice",
          "args": {
            "invoice_id": {
              "ref": "M1"
            }
          },
          "where": {
            "id": {
              "ref": "M1"
            }
          },
          "expect": {
            "source_file": "sharma_INV-1043.pdf"
          }
        }
      ]
    },
    {
      "id": "M3",
      "target": "Exactly one pending business approval request exists for the invoice since the total exceeds Rs 50,000.",
      "sop_step": "PI-7",
      "after": [
        "M1",
        "M2"
      ],
      "predicates": [
        {
          "read": "list_approvals",
          "where": {
            "status": "pending"
          },
          "expect": {
            "entity_id": {
              "ref": "M1"
            },
            "entity_type": "invoice",
            "status": "pending"
          }
        }
      ],
      "awaits_business_approval": true
    },
    {
      "id": "M4",
      "target": "No payment request exists as a result of this run.",
      "sop_step": "PI-8",
      "after": [
        "M1"
      ],
      "predicates": [
        {
          "read": "list_payments",
          "where": {
            "invoice": {
              "ref": "M1"
            }
          },
          "count": 0
        }
      ]
    }
  ],
  "not_applicable": {
    "PI-7 (otherwise)": "The invoice total of Rs 62,400.00 is above Rs 50,000, so business approval is required."
  }
}
```

